import React from 'react';

const cameras = [
  { id: 1, name: 'Camera 01 - Main Gate', detection: 'Normal 0.92', detColor: '#22c55e', borderColor: '#1e2d47' },
  { id: 2, name: 'Camera 02 - Parking',   detection: 'Fire 0.93',   detColor: '#ef4444', borderColor: '#7f1d1d' },
  { id: 3, name: 'Camera 03 - Corridor',  detection: 'Violence 0.91', detColor: '#a855f7', borderColor: '#7f1d3f' },
  { id: 4, name: 'Camera 04 - Office',    detection: 'Normal 0.88', detColor: '#22c55e', borderColor: '#1e2d47' },
];

export default function CameraGrid() {
  return (
    <div style={{ marginBottom: 12 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 8 }}>
        <span style={{ color: '#3b82f6' }}>📷</span>
        <span style={{ fontSize: 11, fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '.5px' }}>Live Cameras</span>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 8 }}>
        {cameras.map(cam => (
          <div key={cam.id} style={{
            background: '#151d2e', border: `1px solid ${cam.borderColor}`,
            borderRadius: 8, overflow: 'hidden'
          }}>
            {/* Header */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '5px 8px', background: '#1a2340' }}>
              <span style={{ fontSize: 10, fontWeight: 600, color: '#e2e8f0' }}>{cam.name}</span>
              <span style={{ fontSize: 9, color: '#22c55e', display: 'flex', alignItems: 'center', gap: 3 }}>
                <span style={{ width: 6, height: 6, borderRadius: '50%', background: '#22c55e', display: 'inline-block', animation: 'pulse 1.5s infinite' }}></span>
                Live
              </span>
            </div>

            {/* Feed */}
            <div style={{ height: 110, background: '#080f1a', position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <span style={{ fontSize: 10, color: '#253550' }}>[ Camera Feed ]</span>
              <div style={{
                position: 'absolute', border: `2px solid ${cam.detColor}`,
                borderRadius: 3, padding: '2px 5px', fontSize: 9, fontWeight: 700,
                color: cam.detColor, background: `${cam.detColor}22`,
                top: '20%', left: '20%'
              }}>
                {cam.detection}
              </div>
            </div>

            {/* Footer */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '4px 8px', background: '#1a2340' }}>
              <span style={{ fontSize: 12, color: '#64748b', cursor: 'pointer' }}>📷</span>
              <span style={{ fontSize: 12, color: '#64748b', cursor: 'pointer' }}>⛶</span>
              <span style={{ fontSize: 12, color: '#64748b', cursor: 'pointer' }}>⋯</span>
              <div style={{ display: 'flex', gap: 1, alignItems: 'flex-end' }}>
                {[4, 6, 8, 10].map((h, i) => (
                  <span key={i} style={{ width: 2, height: h, background: '#22c55e', borderRadius: 1, display: 'block' }}></span>
                ))}
              </div>
            </div>
          </div>
        ))}

        {/* Add Camera Slots */}
        {[1, 2].map(i => (
          <div key={i} style={{
            background: '#151d2e', border: '1px dashed #253550',
            borderRadius: 8, height: 145, display: 'flex',
            flexDirection: 'column', alignItems: 'center',
            justifyContent: 'center', cursor: 'pointer',
            color: '#64748b', gap: 4
          }}
            onMouseEnter={e => { e.currentTarget.style.borderColor = '#3b82f6'; e.currentTarget.style.color = '#3b82f6'; }}
            onMouseLeave={e => { e.currentTarget.style.borderColor = '#253550'; e.currentTarget.style.color = '#64748b'; }}
          >
            <span style={{ fontSize: 24 }}>+</span>
            <span style={{ fontSize: 11, fontWeight: 500 }}>Add Camera</span>
            <span style={{ fontSize: 9 }}>Click to add new camera</span>
          </div>
        ))}
      </div>
    </div>
  );
}
